namespace Ogre
{
    extern int fontTextureCounter;

    class VRbxFont
    {
        int subWidth[128];
        int charWidth;
        int charHeight;
        int baseline;
        TexturePtr texture;

    public:
        VRbxFont(const String& filename, G3D::BinaryInput& input);
    };

    typedef char VRbxFont_size_is_0x218[sizeof(VRbxFont) == 0x218 ? 1 : -1];

    VRbxFont::VRbxFont(const String& filename, G3D::BinaryInput& input)
        : texture()
    {
        input.readInt32();

        for (int c = 0; c < 128; ++c)
            subWidth[c] = input.readUInt16();

        baseline = input.readUInt16();
        int textureWidth = input.readUInt16();
        charWidth = textureWidth / 16;
        charHeight = textureWidth / 16;

        int width = G3D::ceilPow2(charWidth * 16);
        int height = G3D::ceilPow2(charHeight * 8);

