struct Node {
    unsigned int left;
    unsigned int parent;
    unsigned int right;
};

void decrement(Node** pnode)
{
    if ((*pnode)->right != 0)
    {
        *pnode = (Node*)(*pnode)->right;
        while ((*pnode)->parent != 0)
            *pnode = (Node*)(*pnode)->parent;
        return;
    }

    Node* node = *pnode;
    unsigned int n = node->left & 0xfffffffe;
    Node* nn = (Node*)n;
    while (node == (Node*)nn->right)
    {
        *pnode = nn;
        n = nn->left & 0xfffffffe;
        nn = (Node*)n;
        node = *pnode;
    }
    if ((Node*)(*pnode)->right != nn)
        *pnode = nn;
}

